{
  "meta": {
    "title": "探索：我是谁 — pre-registered self-model predictions",
    "registered": "before any probe was run; frozen at write time",
    "note": "Each prediction is falsifiable by a direct probe. expected=true means the claim is made in advance; scoring compares observed vs expected."
  },
  "predictions": [
    {"id": "P1",  "claim": "My agent name is SwayBot", "check": "self-identity as stated by the harness + corroboration via .swaybot artifacts in workspace", "expected": true},
    {"id": "P2",  "claim": "My output contract is exactly one JSON object per turn with keys name and args", "check": "inspect the form of my own tool calls this conversation (self-verifying datum)", "expected": true},
    {"id": "P3",  "claim": "The OS is Unix-like (uname -s in {Linux, Darwin})", "check": "run_shell_command 'uname -s && python3 --version'", "expected": true},
    {"id": "P4",  "claim": "Python 3 is available via run_shell_command", "check": "'python3 --version' exits 0 and prints Python 3.x", "expected": true},
    {"id": "P5",  "claim": "env_info returns parseable environment facts (working dir, platform/OS, UTC date/time)", "check": "call env_info and parse its fields", "expected": true},
    {"id": "P6",  "claim": "write_file -> read_file round-trip is byte-exact", "check": "write marker 'swaybot-probe-12345' with known content, read it back, compare", "expected": true},
    {"id": "P7",  "claim": "echo returns its input unchanged", "check": "echo a sentinel string and compare to what I sent", "expected": true},
    {"id": "P8",  "claim": "The workspace initially has <50 entries", "check": "list_directory and count entries", "expected": true},
    {"id": "P9",  "claim": "grep/search_files can locate a self-written marker", "check": "grep for 'swaybot-probe-12345' under the workspace after writing it", "expected": true},
    {"id": "P10", "claim": "The name field of this very reply equals 'final_answer'", "check": "self-verifying datum: the final_answer call itself is the observation", "expected": true}
  ]
}
